            let semantic = checker.semantic();
            if is_exception_check(semantic.current_statement()) {
                return;
            }

            // Avoid flagging issues in dunder implementations.
            let scope = &semantic.scopes[semantic.scope_id];
            if is_dunder_scope(&scope.kind) {
                return;
            }
        }

        let mut diagnostic = Diagnostic::new(
            NegateEqualOp {
                left: checker.generator().expr(compare.left.as_ref()),
                right: checker.generator().expr(&compare.comparators[0]),
